-- Read-only, after the first crawl. Generated by Build-Sql.py.
SELECT 'feed|' || p.id || '|' || p.name || '|' || f.consecutive_failures || '|' || coalesce(to_char(f.last_success_at, 'HH24:MI'), 'never')
       || '|' || coalesce(left(f.last_error, 80), '-')
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id) || ' art'
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id AND a.published_at IS NULL) || ' undated'
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id AND a.headline LIKE '%(Abo)') || ' with (Abo)'
  FROM publisher_submissions s JOIN publishers p ON p.id = s.publisher_id JOIN feeds f ON f.publisher_id = p.id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #101 Vaterland crawl]';
SELECT 'ok|' || count(*) FILTER (WHERE f.last_success_at > now() - interval '40 minutes') || ' of 1'
  FROM publisher_submissions s JOIN feeds f ON f.publisher_id = s.publisher_id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #101 Vaterland crawl]';
SELECT 'sample|' || to_char(a.published_at, 'YYYY-MM-DD') || '|' || a.category || '|' || left(a.headline, 80)
  FROM articles a JOIN publisher_submissions s ON s.publisher_id = a.publisher_id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #101 Vaterland crawl]' ORDER BY a.id DESC LIMIT 3;
